// The permission text a learner reads must be the text we wrote.
//
// `mobile/ios/` is GENERATED by `expo prebuild` and is gitignored (see
// mobile/.gitignore line 42), so app.json is the single source of truth and
// Info.plist is a build artifact. Two things follow, and they are different
// checks rather than one check with a get-out:
//
//   1. ALWAYS, including in CI where no ios/ exists: app.json must declare a
//      usage description for every permission the app actually asks for. iOS
//      terminates an app the instant it touches a protected API with no
//      description, so a missing declaration is a crash on a learner's phone,
//      and it is invisible until prebuild has run.
//
//   2. ONLY where a generated ios/ exists: that plist must still match app.json.
//      A stale prebuild is what actually gets compiled and installed, so a
//      developer editing app.json and building without re-running prebuild ships
//      the OLD text. That happened: the microphone description shipped to a
//      device predating the text in app.json.
//
// Skipping (2) in CI is not the comfortable-default pattern. There is genuinely
// no artifact there to be stale, and (1), the assertion that protects against a
// crash, runs everywhere.
import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const MOBILE = dirname(dirname(fileURLToPath(import.meta.url)));
const PLIST = join(MOBILE, 'ios', 'Ohmlet', 'Info.plist');

const app = JSON.parse(readFileSync(join(MOBILE, 'app.json'), 'utf8'));
const declared = app?.expo?.ios?.infoPlist ?? {};

let bad = 0;
const fail = (m) => { bad += 1; console.error(`  FAIL  ${m}`); };

// ── 1. Every permission the app uses is declared ────────────────────────────
//
// Derived from what the source actually calls, not from a list somebody
// remembered to update. A new permission-touching API with no description is
// the crash this exists to prevent.
const SRC = join(MOBILE, 'src');
const sources = [];
const walk = (dir) => {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) walk(full);
    else if (/\.(ts|tsx)$/.test(entry.name)) sources.push(readFileSync(full, 'utf8'));
  }
};
walk(SRC);
const code = sources.join('\n');

const USES = [
  { key: 'NSCameraUsageDescription', why: 'the camera', signals: [/expo-camera/, /CameraView/, /useCameraPermissions/] },
  { key: 'NSMicrophoneUsageDescription', why: 'the microphone', signals: [/AudioRecorder/, /requestRecordingPermissions/, /react-native-audio-api/] },
];

for (const { key, why, signals } of USES) {
  const used = signals.some((re) => re.test(code));
  const text = declared[key];
  if (used && !text) {
    fail(`the app uses ${why} but app.json declares no ${key}, so iOS terminates it the moment it asks`);
  }
  if (used && typeof text === 'string' && text.trim().length < 20) {
    fail(`${key} is too short to explain anything: ${JSON.stringify(text)}`);
  }
}
const usedCount = USES.filter(({ signals }) => signals.some((re) => re.test(code))).length;

// ── 1b. A config plugin must not be quietly overriding the declaration ──────
//
// There are THREE places a usage string can live, not two, and the one that
// looks authoritative loses. `expo.ios.infoPlist` is the obvious declaration;
// the react-native-audio-api config PLUGIN takes its own
// `iosMicrophonePermission` and writes the plist during prebuild, AFTER the
// infoPlist block. So editing infoPlist alone changes nothing: prebuild put the
// plugin's older sentence straight back, and the infoPlist value sat there
// reading like the source of truth while being a decoy.
const PLUGIN_OVERRIDES = [
  { plugin: 'react-native-audio-api', option: 'iosMicrophonePermission', key: 'NSMicrophoneUsageDescription' },
];

for (const { plugin, option, key } of PLUGIN_OVERRIDES) {
  const entry = (app?.expo?.plugins ?? []).find((e) => Array.isArray(e) && e[0] === plugin);
  if (!entry) continue;
  const viaPlugin = entry[1]?.[option];
  if (viaPlugin === undefined) continue;
  if (declared[key] !== undefined && viaPlugin !== declared[key]) {
    fail(`${plugin} sets ${option}, which OVERRIDES ${key} at prebuild time, and the two disagree.\n`
      + `          ios.infoPlist: ${declared[key]}\n`
      + `          ${plugin}: ${viaPlugin}\n`
      + `        The plugin wins, so the infoPlist value is a decoy. Set both.`);
  }
}

// ── 2. A generated plist, if there is one, must not be stale ────────────────
let compared = 0;
if (existsSync(PLIST)) {
  const xml = readFileSync(PLIST, 'utf8');
  if (!xml.startsWith('<?xml')) {
    fail('ios/Ohmlet/Info.plist is not XML, so this check cannot read it. Re-run expo prebuild.');
  } else {
    const unescapeXml = (s) => s
      .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
      .replace(/&quot;/g, '"').replace(/&apos;/g, "'")
      .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d)))
      .replace(/&amp;/g, '&');
    const fromPlist = (key) => {
      const at = xml.indexOf(`<key>${key}</key>`);
      if (at === -1) return null;
      const rest = xml.slice(at + `<key>${key}</key>`.length);
      const m = rest.match(/^\s*<string>([\s\S]*?)<\/string>/);
      return m ? unescapeXml(m[1]) : null;
    };
    for (const key of Object.keys(declared).filter((k) => k.startsWith('NS') && k.endsWith('UsageDescription'))) {
      const shipped = fromPlist(key);
      compared += 1;
      if (shipped === null) {
        fail(`${key} is in app.json but not in your generated Info.plist. Run \`npx expo prebuild --clean\` before building, or the build ships without it and iOS terminates the app.`);
      } else if (shipped !== declared[key]) {
        fail(`${key} in your generated Info.plist is STALE. A build made now installs the old text.\n`
          + `          app.json:   ${declared[key]}\n`
          + `          Info.plist: ${shipped}\n`
          + '        Run `npx expo prebuild` to regenerate it.');
      }
    }
  }
}

if (bad === 0) {
  console.log(`  ok    app.json declares a usage description for all ${usedCount} permissions the source actually uses`);
  console.log(compared
    ? `  ok    the generated Info.plist matches app.json on all ${compared} of them`
    : '  note  no generated ios/ here, so there is no build artifact to be stale (this is the CI case)');
}
console.log(bad === 0 ? '\nusage strings: all checks passed' : `\nusage strings: ${bad} failure(s)`);
process.exit(bad === 0 ? 0 : 1);
